<script setup>import{ref,onMounted}from'vue';import{useRoute}from'vue-router';import{ElMessage}from'element-plus';import PageHeader from'../components/PageHeader.vue';import{getRequirement,updateRequirement}from'../api/admin.js';const route=useRoute(),item=ref();onMounted(async()=>item.value=(await getRequirement(route.params.id)).data);async function accept(){await updateRequirement(item.value.id,{status:'已受理'});item.value.status='已受理';ElMessage.success('需求已受理')}</script>
<template><div class="admin-page" v-if="item"><PageHeader title="需求详情" :description="item.id"><el-button @click="$router.back()">返回</el-button><el-button type="primary" @click="accept">标记已受理</el-button></PageHeader><div class="split"><section class="work-surface detail-section"><h2 class="section-title">客户需求</h2><dl class="detail-list"><dt>客户</dt><dd>{{item.customer}} · {{item.phone}}</dd><dt>定制空间</dt><dd>{{item.space}}</dd><dt>偏好风格</dt><dd>{{item.style}}</dd><dt>预算范围</dt><dd>{{item.budget}}</dd><dt>空间尺寸</dt><dd>{{item.size}}</dd><dt>材料偏好</dt><dd>{{item.materials}}</dd><dt>需求描述</dt><dd>{{item.description}}</dd><dt>户型文件</dt><dd><a style="color:var(--primary)">户型图_{{item.id}}.pdf</a></dd></dl></section><aside class="work-surface detail-section"><h2 class="section-title">处理信息</h2><dl class="detail-list"><dt>状态</dt><dd><span class="status warning">{{item.status}}</span></dd><dt>负责人</dt><dd>{{item.owner}}</dd><dt>提交时间</dt><dd>{{item.submittedAt}}</dd></dl><el-button style="width:100%;margin-top:24px">分派设计师</el-button></aside></div></div></template><style scoped>.detail-section{padding:24px 28px;min-height:300px}</style>
